40	const sumBasePremiums = (items: Item[]): number => {
41	  const nonComponents = items.filter((it) => !isComponent(it));
42	  const components = items.filter(isComponent);
43	  const nonCompTotal = nonComponents.reduce((sum, item) => sum + basePremiumOf(item), 0);
44	  const counts = countByType(components);
